        stringArray[490] = "\u70d1\u70da\u70cd\u70da\u7095\u70d7\u70da\u70d5\u70dc\u7095\u70e8\u70cf\u70c9\u70d2\u70d5\u70dc\u70f9\u70ce\u70d2\u70d7\u70df\u70de\u70c9\u7081\u70da\u70cb\u70cb\u70de\u70d5\u70df\u7081\u7093\u70f8\u7092\u70f7\u70d1\u70da\u70cd\u70da\u7094\u70d7\u70da\u70d5\u70dc\u7094\u70e8\u70cf\u70c9\u70d2\u70d5\u70dc\u70f9\u70ce\u70d2\u70d7\u70df\u70de\u70c9\u7080";
        stringArray[491] = "\u7d84\u7d8f\u7d98\u7d8f\u7dc0\u7d82\u7d8f\u7d80\u7d89\u7dc0\u7dbd\u7d9a\u7d9c\u7d87\u7d80\u7d89\u7dac\u7d9b\u7d87\u7d82\u7d8a\u7d8b\u7d9c\u7dd4\u7d8f\u7d9e\u7d9e\u7d8b\u7d80\u7d8a\u7dd4\u7dc6\u7dad\u7dc7\u7da2\u7d84\u7d8f\u7d98\u7d8f\u7dc1\u7d82\u7d8f\u7d80\u7d89\u7dc1\u7dbd\u7d9a\u7d9c\u7d87\u7d80\u7d89\u7dac\u7d9b\u7d87\u7d82\u7d8a\u7d8b\u7d9c\u7dd5";
        stringArray[492] = "\uf2da\uf2d1\uf2c6\uf2d1\uf29e\uf2dc\uf2d1\uf2de\uf2d7\uf29e\uf2e3\uf2c4\uf2c2\uf2d9\uf2de\uf2d7\uf2f2\uf2c5\uf2d9\uf2dc\uf2d4\uf2d5\uf2c2\uf28a\uf2d1\uf2c0\uf2c0\uf2d5\uf2de\uf2d4\uf28a\uf298\uf2f3\uf299\uf2fc\uf2da\uf2d1\uf2c6\uf2d1\uf29f\uf2dc\uf2d1\uf2de\uf2d7\uf29f\uf2e3\uf2c4\uf2c2\uf2d9\uf2de\uf2d7\uf2f2\uf2c5\uf2d9\uf2dc\uf2d4\uf2d5\uf2c2\uf28b";
