        stringArray[849] = "\u54cc\u54c7\u54d0\u54c7\u5488\u54c8\u54cf\u54c9\u5488\u54c0\u54cf\u54ca\u54c3\u5488\u54f6\u54c7\u54d2\u54ce\u549c\u54c9\u54c0\u549c\u548e\u54ea\u54cc\u54c7\u54d0\u54c7\u5489\u54ca\u54c7\u54c8\u54c1\u5489\u54f5\u54d2\u54d4\u54cf\u54c8\u54c1\u549d\u54fd\u54ea\u54cc\u54c7\u54d0\u54c7\u5489\u54ca\u54c7\u54c8\u54c1\u5489\u54f5\u54d2\u54d4\u54cf\u54c8\u54c1\u549d\u548f\u54ea\u54cc\u54c7\u54d0\u54c7\u5489\u54c8\u54cf\u54c9\u5489\u54c0\u54cf\u54ca\u54c3\u5489\u54f6\u54c7\u54d2\u54ce\u549d";
        stringArray[850] = "\ub7b6\ub7bd\ub7aa\ub7bd\ub7f2\ub7b2\ub7b5\ub7b3\ub7f2\ub7ba\ub7b5\ub7b0\ub7b9\ub7f2\ub79a\ub7b5\ub7b0\ub7b9\ub7af\ub7e6\ub7bf\ub7ae\ub7b9\ub7bd\ub7a8\ub7b9\ub798\ub7b5\ub7ae\ub7b9\ub7bf\ub7a8\ub7b3\ub7ae\ub7b5\ub7b9\ub7af\ub7e6\ub7f4\ub790\ub7b6\ub7bd\ub7aa\ub7bd\ub7f3\ub7b2\ub7b5\ub7b3\ub7f3\ub7ba\ub7b5\ub7b0\ub7b9\ub7f3\ub78c\ub7bd\ub7a8\ub7b4\ub7e7\ub787\ub790\ub7b6\ub7bd\ub7aa\ub7bd\ub7f3\ub7b2\ub7b5\ub7b3\ub7f3\ub7ba\ub7b5\ub7b0\ub7b9\ub7f3\ub7bd\ub7a8\ub7a8\ub7ae\ub7b5\ub7be\ub7a9\ub7a8\ub7b9\ub7f3\ub79a\ub7b5\ub7b0\ub7b9\ub79d\ub7a8\ub7a8\ub7ae\ub7b5\ub7be\ub7a9\ub7a8\ub7b9\ub7e7\ub7f5\ub790\ub7b6\ub7bd\ub7aa\ub7bd\ub7f3\ub7b2\ub7b5\ub7b3\ub7f3\ub7ba\ub7b5\ub7b0\ub7b9\ub7f3\ub78c\ub7bd\ub7a8\ub7b4\ub7e7";
