        stringArray[960] = "\ufc0e\ufc05\ufc12\ufc05\ufc4a\ufc08\ufc05\ufc0a\ufc03\ufc4a\ufc37\ufc10\ufc16\ufc0d\ufc0a\ufc03\ufc26\ufc11\ufc0d\ufc08\ufc00\ufc01\ufc16\ufc5e\ufc05\ufc14\ufc14\ufc01\ufc0a\ufc00\ufc5e\ufc4c\ufc27\ufc4d\ufc28\ufc0e\ufc05\ufc12\ufc05\ufc4b\ufc08\ufc05\ufc0a\ufc03\ufc4b\ufc37\ufc10\ufc16\ufc0d\ufc0a\ufc03\ufc26\ufc11\ufc0d\ufc08\ufc00\ufc01\ufc16\ufc5f";
