        stringArray[965] = "\u766f\u7664\u7673\u7664\u762b\u7669\u7664\u766b\u7662\u762b\u7656\u7671\u7677\u766c\u766b\u7662\u7647\u7670\u766c\u7669\u7661\u7660\u7677\u763f\u7664\u7675\u7675\u7660\u766b\u7661\u763f\u762d\u7646\u762c\u7649\u766f\u7664\u7673\u7664\u762a\u7669\u7664\u766b\u7662\u762a\u7656\u7671\u7677\u766c\u766b\u7662\u7647\u7670\u766c\u7669\u7661\u7660\u7677\u763e";
