        stringArray[1056] = "\uc47d\uc476\uc461\uc476\uc439\uc47b\uc476\uc479\uc470\uc439\uc454\uc47b\uc476\uc464\uc464\uc42d\uc470\uc472\uc463\uc45a\uc472\uc463\uc47f\uc478\uc473\uc464\uc42d\uc43f\uc43e\uc44c\uc45b\uc47d\uc476\uc461\uc476\uc438\uc47b\uc476\uc479\uc470\uc438\uc465\uc472\uc471\uc47b\uc472\uc474\uc463\uc438\uc45a\uc472\uc463\uc47f\uc478\uc473\uc42c";
