        stringArray[1061] = "\uc869\uc862\uc875\uc862\uc82d\uc86f\uc862\uc86d\uc864\uc82d\uc850\uc877\uc871\uc86a\uc86d\uc864\uc839\uc866\uc872\uc876\uc862\uc86f\uc870\uc839\uc82b\uc84f\uc869\uc862\uc875\uc862\uc82c\uc86f\uc862\uc86d\uc864\uc82c\uc84c\uc861\uc869\uc866\uc860\uc877\uc838\uc82a\uc859";
