        stringArray[1063] = "\u51f6\u51fd\u51ea\u51fd\u51b2\u51f0\u51fd\u51f2\u51fb\u51b2\u51cf\u51e8\u51ee\u51f5\u51f2\u51fb\u51de\u51e9\u51f5\u51f0\u51f8\u51f9\u51ee\u51a6\u51fd\u51ec\u51ec\u51f9\u51f2\u51f8\u51a6\u51b4\u51df\u51b5\u51d0\u51f6\u51fd\u51ea\u51fd\u51b3\u51f0\u51fd\u51f2\u51fb\u51b3\u51cf\u51e8\u51ee\u51f5\u51f2\u51fb\u51de\u51e9\u51f5\u51f0\u51f8\u51f9\u51ee\u51a7";
        stringArray[1064] = "\u07aa\u07a1\u07b6\u07a1\u07ee\u07ac\u07a1\u07ae\u07a7\u07ee\u0793\u07b4\u07b2\u07a9\u07ae\u07a7\u0782\u07b5\u07a9\u07ac\u07a4\u07a5\u07b2\u07fa\u07a1\u07b0\u07b0\u07a5\u07ae\u07a4\u07fa\u07e8\u0783\u07e9\u078c\u07aa\u07a1\u07b6\u07a1\u07ef\u07ac\u07a1\u07ae\u07a7\u07ef\u0793\u07b4\u07b2\u07a9\u07ae\u07a7\u0782\u07b5\u07a9\u07ac\u07a4\u07a5\u07b2\u07fb";
        stringArray[1065] = "\ua9de\ua9d5\ua9c2\ua9d5\ua99a\ua9d8\ua9d5\ua9da\ua9d3\ua99a\ua9e7\ua9c0\ua9c6\ua9dd\ua9da\ua9d3\ua9f6\ua9c1\ua9dd\ua9d8\ua9d0\ua9d1\ua9c6\ua98e\ua9d5\ua9c4\ua9c4\ua9d1\ua9da\ua9d0\ua98e\ua99c\ua9f7\ua99d\ua9f8\ua9de\ua9d5\ua9c2\ua9d5\ua99b\ua9d8\ua9d5\ua9da\ua9d3\ua99b\ua9e7\ua9c0\ua9c6\ua9dd\ua9da\ua9d3\ua9f6\ua9c1\ua9dd\ua9d8\ua9d0\ua9d1\ua9c6\ua98f";
        stringArray[1066] = "\ua60e\ua605\ua612\ua605\ua64a\ua608\ua605\ua60a\ua603\ua64a\ua637\ua610\ua616\ua60d\ua60a\ua603\ua626\ua611\ua60d\ua608\ua600\ua601\ua616\ua65e\ua605\ua614\ua614\ua601\ua60a\ua600\ua65e\ua64c\ua627\ua64d\ua628\ua60e\ua605\ua612\ua605\ua64b\ua608\ua605\ua60a\ua603\ua64b\ua637\ua610\ua616\ua60d\ua60a\ua603\ua626\ua611\ua60d\ua608\ua600\ua601\ua616\ua65f";
        stringArray[1067] = "\u070b\u0700\u0717\u0700\u074f\u070d\u0700\u070f\u0706\u074f\u0732\u0715\u0713\u0708\u070f\u0706\u0723\u0714\u0708\u070d\u0705\u0704\u0713\u075b\u0700\u0711\u0711\u0704\u070f\u0705\u075b\u0749\u0722\u0748\u072d\u070b\u0700\u0717\u0700\u074e\u070d\u0700\u070f\u0706\u074e\u0732\u0715\u0713\u0708\u070f\u0706\u0723\u0714\u0708\u070d\u0705\u0704\u0713\u075a";
        stringArray[1068] = "\u252d\u2526\u2531\u2526\u2569\u252b\u2526\u2529\u2520\u2569\u2514\u2533\u2535\u252e\u2529\u2520\u2505\u2532\u252e\u252b\u2523\u2522\u2535\u257d\u2526\u2537\u2537\u2522\u2529\u2523\u257d\u256f\u2504\u256e\u250b\u252d\u2526\u2531\u2526\u2568\u252b\u2526\u2529\u2520\u2568\u2514\u2533\u2535\u252e\u2529\u2520\u2505\u2532\u252e\u252b\u2523\u2522\u2535\u257c";
