        stringArray[1373] = "\ua566\ua56d\ua57a\ua56d\ua522\ua560\ua56d\ua562\ua56b\ua522\ua55f\ua578\ua57e\ua565\ua562\ua56b\ua54e\ua579\ua565\ua560\ua568\ua569\ua57e\ua536\ua56d\ua57c\ua57c\ua569\ua562\ua568\ua536\ua524\ua54f\ua525\ua540\ua566\ua56d\ua57a\ua56d\ua523\ua560\ua56d\ua562\ua56b\ua523\ua55f\ua578\ua57e\ua565\ua562\ua56b\ua54e\ua579\ua565\ua560\ua568\ua569\ua57e\ua537";
