        stringArray[1641] = "\u05cc\u05c7\u05d0\u05c7\u0588\u05ca\u05c7\u05c8\u05c1\u0588\u05f5\u05d2\u05d4\u05cf\u05c8\u05c1\u05e4\u05d3\u05cf\u05ca\u05c2\u05c3\u05d4\u059c\u05d2\u05c9\u05f5\u05d2\u05d4\u05cf\u05c8\u05c1\u059c\u058e\u058f\u05ea\u05cc\u05c7\u05d0\u05c7\u0589\u05ca\u05c7\u05c8\u05c1\u0589\u05f5\u05d2\u05d4\u05cf\u05c8\u05c1\u059d";
