        stringArray[1760] = "\u0551\u055a\u054d\u055a\u0515\u0557\u055a\u0555\u055c\u0515\u0568\u054f\u0549\u0552\u0555\u055c\u0579\u054e\u0552\u0557\u055f\u055e\u0549\u0501\u055a\u054b\u054b\u055e\u0555\u055f\u0501\u0513\u0578\u0512\u0577\u0551\u055a\u054d\u055a\u0514\u0557\u055a\u0555\u055c\u0514\u0568\u054f\u0549\u0552\u0555\u055c\u0579\u054e\u0552\u0557\u055f\u055e\u0549\u0500";
