        stringArray[1986] = "\u2e87\u2e8c\u2e9b\u2e8c\u2ec3\u2e81\u2e8c\u2e83\u2e8a\u2ec3\u2ebe\u2e99\u2e9f\u2e84\u2e83\u2e8a\u2eaf\u2e98\u2e84\u2e81\u2e89\u2e88\u2e9f\u2ed7\u2e8c\u2e9d\u2e9d\u2e88\u2e83\u2e89\u2ed7\u2ec5\u2eae\u2ec4\u2ea1\u2e87\u2e8c\u2e9b\u2e8c\u2ec2\u2e81\u2e8c\u2e83\u2e8a\u2ec2\u2ebe\u2e99\u2e9f\u2e84\u2e83\u2e8a\u2eaf\u2e98\u2e84\u2e81\u2e89\u2e88\u2e9f\u2ed6";
