        stringArray[2005] = "\u4226\u422d\u423a\u422d\u4262\u4220\u422d\u4222\u422b\u4262\u421f\u4238\u423e\u4225\u4222\u422b\u420e\u4239\u4225\u4220\u4228\u4229\u423e\u4276\u422d\u423c\u423c\u4229\u4222\u4228\u4276\u4264\u420f\u4265\u4200\u4226\u422d\u423a\u422d\u4263\u4220\u422d\u4222\u422b\u4263\u421f\u4238\u423e\u4225\u4222\u422b\u420e\u4239\u4225\u4220\u4228\u4229\u423e\u4277";
        stringArray[2006] = "\u3145\u314e\u3159\u314e\u3101\u3143\u314e\u3141\u3148\u3101\u317c\u315b\u315d\u3146\u3141\u3148\u316d\u315a\u3146\u3143\u314b\u314a\u315d\u3115\u314e\u315f\u315f\u314a\u3141\u314b\u3115\u3107\u316c\u3106\u3163\u3145\u314e\u3159\u314e\u3100\u3143\u314e\u3141\u3148\u3100\u317c\u315b\u315d\u3146\u3141\u3148\u316d\u315a\u3146\u3143\u314b\u314a\u315d\u3114";
