        stringArray[2057] = "\u2d4a\u2d41\u2d56\u2d41\u2d0e\u2d4e\u2d49\u2d4f\u2d0e\u2d46\u2d49\u2d4c\u2d45\u2d0e\u2d66\u2d49\u2d4c\u2d45\u2d53\u2d1a\u2d45\u2d58\u2d49\u2d53\u2d54\u2d53\u2d1a\u2d08\u2d6c\u2d4a\u2d41\u2d56\u2d41\u2d0f\u2d4e\u2d49\u2d4f\u2d0f\u2d46\u2d49\u2d4c\u2d45\u2d0f\u2d70\u2d41\u2d54\u2d48\u2d1b\u2d7b\u2d6c\u2d4a\u2d41\u2d56\u2d41\u2d0f\u2d4e\u2d49\u2d4f\u2d0f\u2d46\u2d49\u2d4c\u2d45\u2d0f\u2d6c\u2d49\u2d4e\u2d4b\u2d6f\u2d50\u2d54\u2d49\u2d4f\u2d4e\u2d1b\u2d09\u2d7a";
        stringArray[2058] = "\u350d\u3506\u3511\u3506\u3549\u3509\u350e\u3508\u3549\u3501\u350e\u350b\u3502\u3549\u3521\u350e\u350b\u3502\u3514\u355d\u3515\u3502\u3506\u3503\u3534\u3513\u3515\u350e\u3509\u3500\u355d\u354f\u352b\u350d\u3506\u3511\u3506\u3548\u3509\u350e\u3508\u3548\u3501\u350e\u350b\u3502\u3548\u3537\u3506\u3513\u350f\u355c\u354e\u352b\u350d\u3506\u3511\u3506\u3548\u350b\u3506\u3509\u3500\u3548\u3534\u3513\u3515\u350e\u3509\u3500\u355c";
