        stringArray[2074] = "\u1d88\u1d83\u1d94\u1d83\u1dcc\u1d8e\u1d83\u1d8c\u1d85\u1dcc\u1db1\u1d96\u1d90\u1d8b\u1d8c\u1d85\u1da0\u1d97\u1d8b\u1d8e\u1d86\u1d87\u1d90\u1dd8\u1d83\u1d92\u1d92\u1d87\u1d8c\u1d86\u1dd8\u1dca\u1da1\u1dcb\u1dae\u1d88\u1d83\u1d94\u1d83\u1dcd\u1d8e\u1d83\u1d8c\u1d85\u1dcd\u1db1\u1d96\u1d90\u1d8b\u1d8c\u1d85\u1da0\u1d97\u1d8b\u1d8e\u1d86\u1d87\u1d90\u1dd9";
        stringArray[2075] = "\u26de\u26d5\u26c2\u26d5\u269a\u26d8\u26d5\u26da\u26d3\u269a\u26e7\u26c0\u26c6\u26dd\u26da\u26d3\u26f6\u26c1\u26dd\u26d8\u26d0\u26d1\u26c6\u268e\u26d5\u26c4\u26c4\u26d1\u26da\u26d0\u268e\u269c\u26f7\u269d\u26f8\u26de\u26d5\u26c2\u26d5\u269b\u26d8\u26d5\u26da\u26d3\u269b\u26e7\u26c0\u26c6\u26dd\u26da\u26d3\u26f6\u26c1\u26dd\u26d8\u26d0\u26d1\u26c6\u268f";
        stringArray[2076] = "\u22c1\u22ca\u22dd\u22ca\u2285\u22c7\u22ca\u22c5\u22cc\u2285\u22f8\u22df\u22d9\u22c2\u22c5\u22cc\u22e9\u22de\u22c2\u22c7\u22cf\u22ce\u22d9\u2291\u22ca\u22db\u22db\u22ce\u22c5\u22cf\u2291\u2283\u22e8\u2282\u22e7\u22c1\u22ca\u22dd\u22ca\u2284\u22c7\u22ca\u22c5\u22cc\u2284\u22f8\u22df\u22d9\u22c2\u22c5\u22cc\u22e9\u22de\u22c2\u22c7\u22cf\u22ce\u22d9\u2290";
