        stringArray[2078] = "\u17ae\u17a5\u17b2\u17a5\u17ea\u17a8\u17a5\u17aa\u17a3\u17ea\u1797\u17b0\u17b6\u17ad\u17aa\u17a3\u1786\u17b1\u17ad\u17a8\u17a0\u17a1\u17b6\u17fe\u17a5\u17b4\u17b4\u17a1\u17aa\u17a0\u17fe\u17ec\u1788\u17ae\u17a5\u17b2\u17a5\u17eb\u17a8\u17a5\u17aa\u17a3\u17eb\u1797\u17b0\u17b6\u17ad\u17aa\u17a3\u17ff\u17ed\u1788\u17ae\u17a5\u17b2\u17a5\u17eb\u17a8\u17a5\u17aa\u17a3\u17eb\u1797\u17b0\u17b6\u17ad\u17aa\u17a3\u1786\u17b1\u17ad\u17a8\u17a0\u17a1\u17b6\u17ff";
        stringArray[2079] = "\uefc8\uefc3\uefd4\uefc3\uef8c\uefce\uefc3\uefcc\uefc5\uef8c\ueff1\uefd6\uefd0\uefcb\uefcc\uefc5\uefe0\uefd7\uefcb\uefce\uefc6\uefc7\uefd0\uef98\uefc3\uefd2\uefd2\uefc7\uefcc\uefc6\uef98\uef8a\uefee\uefc8\uefc3\uefd4\uefc3\uef8d\uefce\uefc3\uefcc\uefc5\uef8d\ueff1\uefd6\uefd0\uefcb\uefcc\uefc5\uef99\uef8b\uefee\uefc8\uefc3\uefd4\uefc3\uef8d\uefce\uefc3\uefcc\uefc5\uef8d\ueff1\uefd6\uefd0\uefcb\uefcc\uefc5\uefe0\uefd7\uefcb\uefce\uefc6\uefc7\uefd0\uef99";
