        stringArray[2081] = "\u1f3e\u1f35\u1f22\u1f35\u1f7a\u1f38\u1f35\u1f3a\u1f33\u1f7a\u1f07\u1f20\u1f26\u1f3d\u1f3a\u1f33\u1f16\u1f21\u1f3d\u1f38\u1f30\u1f31\u1f26\u1f6e\u1f20\u1f3b\u1f07\u1f20\u1f26\u1f3d\u1f3a\u1f33\u1f6e\u1f7c\u1f7d\u1f18\u1f3e\u1f35\u1f22\u1f35\u1f7b\u1f38\u1f35\u1f3a\u1f33\u1f7b\u1f07\u1f20\u1f26\u1f3d\u1f3a\u1f33\u1f6f";
        stringArray[2082] = "\u3c5a\u3c51\u3c46\u3c51\u3c1e\u3c5c\u3c51\u3c5e\u3c57\u3c1e\u3c63\u3c44\u3c42\u3c59\u3c5e\u3c57\u3c72\u3c45\u3c59\u3c5c\u3c54\u3c55\u3c42\u3c0a\u3c51\u3c40\u3c40\u3c55\u3c5e\u3c54\u3c0a\u3c18\u3c7c\u3c5a\u3c51\u3c46\u3c51\u3c1f\u3c5c\u3c51\u3c5e\u3c57\u3c1f\u3c63\u3c44\u3c42\u3c59\u3c5e\u3c57\u3c0b\u3c19\u3c7c\u3c5a\u3c51\u3c46\u3c51\u3c1f\u3c5c\u3c51\u3c5e\u3c57\u3c1f\u3c63\u3c44\u3c42\u3c59\u3c5e\u3c57\u3c72\u3c45\u3c59\u3c5c\u3c54\u3c55\u3c42\u3c0b";
