        stringArray[2143] = "\u9d81\u9d8a\u9d9d\u9d8a\u9dc5\u9d87\u9d8a\u9d85\u9d8c\u9dc5\u9db8\u9d9f\u9d99\u9d82\u9d85\u9d8c\u9da9\u9d9e\u9d82\u9d87\u9d8f\u9d8e\u9d99\u9dd1\u9d8a\u9d9b\u9d9b\u9d8e\u9d85\u9d8f\u9dd1\u9dc3\u9da8\u9dc2\u9da7\u9d81\u9d8a\u9d9d\u9d8a\u9dc4\u9d87\u9d8a\u9d85\u9d8c\u9dc4\u9db8\u9d9f\u9d99\u9d82\u9d85\u9d8c\u9da9\u9d9e\u9d82\u9d87\u9d8f\u9d8e\u9d99\u9dd0";
        stringArray[2144] = "\u72b2\u72b9\u72ae\u72b9\u72f6\u72b4\u72b9\u72b6\u72bf\u72f6\u728b\u72ac\u72aa\u72b1\u72b6\u72bf\u729a\u72ad\u72b1\u72b4\u72bc\u72bd\u72aa\u72e2\u72b9\u72a8\u72a8\u72bd\u72b6\u72bc\u72e2\u72f0\u729b\u72f1\u7294\u72b2\u72b9\u72ae\u72b9\u72f7\u72b4\u72b9\u72b6\u72bf\u72f7\u728b\u72ac\u72aa\u72b1\u72b6\u72bf\u729a\u72ad\u72b1\u72b4\u72bc\u72bd\u72aa\u72e3";
