        stringArray[2506] = "\u219d\u2196\u2181\u2196\u21d9\u219b\u2196\u2199\u2190\u21d9\u21a4\u2183\u2185\u219e\u2199\u2190\u21b5\u2182\u219e\u219b\u2193\u2192\u2185\u21cd\u2196\u2187\u2187\u2192\u2199\u2193\u21cd\u21df\u21b4\u21de\u21bb\u219d\u2196\u2181\u2196\u21d8\u219b\u2196\u2199\u2190\u21d8\u21a4\u2183\u2185\u219e\u2199\u2190\u21b5\u2182\u219e\u219b\u2193\u2192\u2185\u21cc";
