        stringArray[2783] = "\u23d5\u23de\u23c9\u23de\u2391\u23d3\u23de\u23d1\u23d8\u2391\u23ec\u23cb\u23cd\u23d6\u23d1\u23d8\u23fd\u23ca\u23d6\u23d3\u23db\u23da\u23cd\u2385\u23cb\u23d0\u23ec\u23cb\u23cd\u23d6\u23d1\u23d8\u2385\u2397\u2396\u23f3\u23d5\u23de\u23c9\u23de\u2390\u23d3\u23de\u23d1\u23d8\u2390\u23ec\u23cb\u23cd\u23d6\u23d1\u23d8\u2384";
